function unpublishedSubmodules(dir: string, initialised: string[] = initializedSubmodules(dir)): string[] {
  return initialised.filter((sub) => {
    const local = git(path.join(dir, sub), ["rev-list", "-n", "1", "HEAD", "--branches", "--tags", "--glob=refs/stash*", "--not", "--remotes"], { allowFailure: true });
    return local.status !== 0 || Boolean(local.stdout.trim());
  });
}

/** True when the entry is an automated task worktree (see `isTaskWorktree`: the shape the task-worktree code creates, never a registered named worktree). */
function isSpeculativeEntry(repo: Repo, entry: { branch?: string | null; path: string }): boolean {
  return isTaskWorktree(repo, entry, readRegistry(repo.commonDir).registry);
}

/** Paths `git status` reports for the worktree, read through the pinned helper (no shell, no fsmonitor, no hooks). */
function changedFiles(dir: string): string[] {
  const records = git(dir, ["status", "--porcelain=v1", "-z", "--untracked-files=normal"]).stdout.split("\0").filter(Boolean);
  const files: string[] = [];
  for (let i = 0; i < records.length; i++) {
    const record = records[i];
    files.push(record.slice(3));
    if (record[0] === "R" || record[0] === "C") i++; // the rename source follows as its own record
  }
  return files;
}

interface InProgressOp { op: string; cmd: string }

function inProgress(gitDir: string): InProgressOp | undefined {
  if (fs.existsSync(path.join(gitDir, "rebase-merge")) || fs.existsSync(path.join(gitDir, "rebase-apply"))) {
    return { op: "rebase", cmd: "git rebase --continue / --abort" };
  }
  if (fs.existsSync(path.join(gitDir, "MERGE_HEAD"))) {
    return { op: "merge", cmd: "git merge --continue / --abort" };
  }
  if (fs.existsSync(path.join(gitDir, "CHERRY_PICK_HEAD"))) {
    return { op: "cherry-pick", cmd: "git cherry-pick --continue / --abort" };
  }
  if (fs.existsSync(path.join(gitDir, "REVERT_HEAD")) || fs.existsSync(path.join(gitDir, "sequencer"))) {
    return { op: "revert", cmd: "git revert --continue / --abort" };
  }
  return undefined;
}

/**
 * The backup ref of a branch: `refs/nexus-backup/<readable name>-<12 hex of sha1(branch)>`. One flat component, so
 * `foo` and `foo/bar` (which Git cannot hold as refs side by side) never collide, and the hash keeps names that
 * sanitise alike apart. List them with `git for-each-ref refs/nexus-backup`.
 */
export function backupRef(branch: string): string {
  const readable = branch.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[.-]+/, "").slice(0, 40) || "branch";
  return `refs/nexus-backup/${readable}-${createHash("sha1").update(branch).digest("hex").slice(0, 12)}`;
}

/** A commit holding the worktree exactly as `git add -A` would see it, stored at backupRef(branch). */
function backup(dir: string, branch: string, dirty: boolean): string {
  let sha = gitOut(dir, ["rev-parse", "--verify", "HEAD"]);
  if (dirty) {
    const tree = workingState(dir, dirty).tree;
    sha = gitOut(dir, ["commit-tree", tree, "-p", sha, "-m", `nexus backup of ${branch} before merge`]);
  try {
    fs.writeFileSync(path.join(f.repo, ".gitignore"), ".nexus/\n");
    git(f.repo, "add", ".gitignore");
    git(f.repo, "commit", "-q", "-m", "ignore .nexus");

    const taskId = "task-spec-123";
    const dir = path.join(f.repo, ".nexus", "worktrees", taskId);
    fs.mkdirSync(path.dirname(dir), { recursive: true });
    git(f.repo, "worktree", "add", "-q", "-b", `nexus/${taskId}`, dir);
    commitFile(dir, "spec.txt", "speculative\n", "speculative work");

    const r = wt(f, dir, ["merge", "^", "--no-remove"]);
    assert.equal(r.success, false, r.output);
    assert.match(r.output, /speculative task worktree/i, r.output);

    const normalDir = feature(f, "feat/normal");
    commitFile(normalDir, "norm.txt", "norm\n", "normal work");
    const r2 = wt(f, normalDir, ["merge", `nexus/${taskId}`, "--no-remove"]);
    assert.equal(r2.success, false, r2.output);
    assert.match(r2.output, /speculative task worktree/i, r2.output);
  } finally { f.cleanup(); }
});

test("a named worktree on a nexus/* branch merges like any other; a task worktree still does not", () => {
  const f = fixture();
  try {
    const dir = feature(f, "nexus/foo");
    assert.equal(dir, dirOf(f, "nexus-foo"));
    commitFile(dir, "foo.txt", "foo\n", "foo work");
    const r = wt(f, dir, ["merge", ...W, "--no-remove"]);
    assert.equal(r.success, true, r.output);
    assert.doesNotMatch(r.output, /speculative/i, r.output);
    assert.equal(git(f.repo, "log", "-1", "--format=%s"), "foo work");

    const taskDir = dirOf(f, "task-abc");
    git(f.repo, "worktree", "add", "-q", "-b", "nexus/task-abc", taskDir);
    commitFile(taskDir, "t.txt", "t\n", "task work");
    const other = feature(f, "feat/other");
    commitFile(other, "o.txt", "o\n", "other work");
    const refused = wt(f, other, ["merge", "nexus/task-abc", ...W, "--no-remove"]);
    assert.equal(refused.success, false, refused.output);
    assert.match(refused.output, /speculative task worktree/i, refused.output);

    const unitDir = path.join(f.repo, ".nexus", "worktrees", "op-k1", "units", "u1");
    git(f.repo, "worktree", "add", "-q", "-b", "nexus/op-k1/u1", unitDir);
    commitFile(unitDir, "u.txt", "u\n", "unit work");
    const unit = wt(f, other, ["merge", "nexus/op-k1/u1", ...W, "--no-remove"]);
    assert.equal(unit.success, false, unit.output);
    assert.match(unit.output, /speculative task worktree/i, unit.output);
  } finally { f.cleanup(); }
});

